INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES
('qa-freshman-001', '怎么用知网下载文献？', '手机知网APP操作路径：个人中心→我的服务→学生认证；认证后使用「全球学术快报」或「知网研学」免费下载文献。', 'resolved', '2026-08-01'),
('qa-freshman-002', '考试怎么申请缓考？', '1. 先取得任课教师同意；2. 登录教务系统提交申请，附件上传《课程缓考申请表》及相关证明材料；3. 经辅导员、学院教务员两级审核通过即完成。已缓考课程再次参加考试需填写《已缓考课程考试申请单》提交至学院教务办公室。', 'resolved', '2026-08-01'),
('qa-freshman-003', '普通话证书怎么补办？', '办理地点：师生服务大厅6号窗口（教务处窗口）。', 'resolved', '2026-08-01'),
('qa-freshman-004', '期末考试时间怎么查？', '两种渠道：任课老师通知、教务处官网公示。', 'resolved', '2026-08-01'),
('qa-freshman-005', '专业排名怎么查？', '无线上查询渠道，联系本班辅导员调取。', 'resolved', '2026-08-01'),
('qa-freshman-006', '期中成绩怎么查？', '教务系统不公示期中成绩，直接询问对应授课老师。', 'resolved', '2026-08-01'),
('qa-freshman-007', '重修和退课的规则是什么？', '退课：开课至两周内可正常退课，每学期限2次；开课两周后需手写申请，任课教师签字后交学院教务员。重修刷绩点：每学期重修及格课程不超过2门，或总学分≤6学分，满足任一即达上限。', 'resolved', '2026-08-01'),
('qa-freshman-008', '怎么查教师和开课信息？', '教师资料查看教师个人主页；全校课程在教务系统「全校开课查询」模块查询。', 'resolved', '2026-08-01'),
('qa-freshman-009', '学校有游泳课吗？', '仅开设校内选修课，学校无付费私教渠道。', 'resolved', '2026-08-01'),
('qa-freshman-010', '补办校园卡后初始密码是什么？', '普通身份证（末尾非X）：身份证后6位；身份证末尾为X：取身份证后7位并去除末尾X作为密码。', 'resolved', '2026-08-01'),
('qa-freshman-011', '校园网怎么充值？', 'i南航APP → 校园卡 → 缴费大厅 → 校园网费充值。', 'resolved', '2026-08-01'),
('qa-freshman-012', '校园网欠费后怎么恢复？', '1. 缴清欠费；2. 访问fuwu.nuaa.edu.cn；3. 页面右侧「更多」→自助服务→账号复通。', 'resolved', '2026-08-01'),
('qa-freshman-013', '校园卡照片怎么换？', '携带身份证前往师生服务大厅，使用现场自助拍照机更换照片。', 'resolved', '2026-08-01'),
('qa-freshman-014', '怎么预约心理咨询？', '预约推送链接：https://mp.weixin.qq.com/s/14pAzEVfijRCIBl3atMIbQ', 'resolved', '2026-08-01'),
('qa-freshman-015', '艺术中心小剧场在哪里？', '艺术中心一楼大厅。', 'resolved', '2026-08-01'),
('qa-freshman-016', '东门几点开门？', '6:30—22:30。', 'resolved', '2026-08-01'),
('qa-freshman-017', '有通宵自习教室吗？', '西区四号楼4101、4102，无课程/考试安排时全天开放。', 'resolved', '2026-08-01'),
('qa-freshman-018', '阳光跑线下申诉去哪里？', '周三16:00–17:30 游泳馆四号门；周四16:00–17:30 游泳馆三号门；周三12:30–14:00 风雨操场航空体育办公室。', 'resolved', '2026-08-01'),
('qa-freshman-019', '跨校区班车在哪里坐？', '将军路→明故宫：东区天桥下方、西区国旗广场两处乘车点。', 'resolved', '2026-08-01'),
('qa-freshman-020', '明故宫校区朗读教室在哪？', '727教室，门口设有专属门牌。', 'resolved', '2026-08-01'),
('qa-freshman-021', '明故宫校区有哪些食堂？', '共5个：一食堂、二食堂、美食园餐厅、航天餐厅（清真民族风味）、风味轩餐厅。', 'resolved', '2026-08-01'),
('qa-freshman-022', '校医院可以借拐杖吗？', '可以，需100元现金押金，每日使用费1元。', 'resolved', '2026-08-01'),
('qa-freshman-023', '东西丢了去哪里找？', '1. 线下通用：师生服务大厅8号窗口；2. 图书馆遗失：图书馆二楼咨询台（物品留存一周，无人认领移交学生事务服务中心）；3. 线上渠道：微信公众号「微爷」后台回复「寻物」，登记信息等待匹配通知。', 'resolved', '2026-08-01'),
('qa-freshman-024', '在校内可以办港澳通行证吗？', '可以，师生服务大厅三号公安政务窗口办理出入境证件。', 'resolved', '2026-08-01'),
('qa-freshman-025', '自行车可以骑出校门吗？', '完成挂牌登记的车辆仅可校内骑行，禁止驶出校门。', 'resolved', '2026-08-01'),
('qa-freshman-026', '校外车能进学校吗？', '原则禁止入校；特殊情况提前联系辅导员报备申请。', 'resolved', '2026-08-01'),
('qa-freshman-027', '校友卡怎么申请？', 'i南航无法办理时，关注公众号「南京航空航天大学校友会」，在公众号服务大厅申领，可添加随行人员。', 'resolved', '2026-08-01'),
('qa-freshman-028', '阳光跑异常怎么申诉？', '1. 线上：公众号「龙猫体育校园平台」→阳光跑→异常申诉，上传跑步截图提交；2. 线下：携带跑步记录截图前往本校区体育办公室现场办理。', 'resolved', '2026-08-01'),
('qa-freshman-029', '师生服务大厅各个窗口是办什么的？', '3号窗口：出入境证件办理；6号窗口：普通话证书补办；8号窗口：失物查询；另设有自助拍照机更换校园卡照片。', 'resolved', '2026-08-01'),
('qa-freshman-030', '退课、重修材料交给谁？', '学院教务员。', 'resolved', '2026-08-01'),
('qa-freshman-031', '专业排名、校外车辆入校找谁？', '本班辅导员。', 'resolved', '2026-08-01'),
('qa-freshman-032', '天目湖校区有哪些常用电话？', '综合报修：0519-88970666 心理中心值班：0519-88970525 保卫处值班：0519-88970000 饮食服务/餐厅：0519-88970799 公寓/宿舍服务：0519-88970913 菜鸟驿站：0519-88970588 信件收发：0519-88970500 服务投诉：0519-88970919 车辆调度：0519-88970506 绿化保洁服务：0519-88970512', 'resolved', '2026-08-01'),
('qa-freshman-033', '综合报修电话是多少？', '0519-88970666', 'resolved', '2026-08-01'),
('qa-freshman-034', '心理中心的电话是多少？', '0519-88970525', 'resolved', '2026-08-01'),
('qa-freshman-035', '宿舍服务电话是多少？', '0519-88970913', 'resolved', '2026-08-01'),
('qa-freshman-036', '迎新网怎么登录？', '等后期学号分配下来后，才能通过学号进行登录。', 'resolved', '2026-08-01'),
('qa-freshman-037', '迎新网站显示考生号或密码错误怎么办？', '考生号为14位数字，大部分地区格式为“25 + 身份证前两位 + 准考证号”；密码为“大写S + 小写t + 身份证后6位”，注意区分大小写。', 'resolved', '2026-08-01'),
('qa-freshman-038', 'i南航、统一门户等平台登录不上怎么办？', '目前除迎新网外，其他平台（缴费、i南航、统一门户、公众号绑定学号等）都还无法登录，需等系统开放后再试。', 'resolved', '2026-08-01'),
('qa-freshman-039', '学号怎么看出是哪个班级？', '学号为aabbcccdd格式：aa为院号，bb为年份，cccc为班级号，dd为班内序号；班级号是学号前7位。', 'resolved', '2026-08-01'),
('qa-freshman-040', '学号和宿舍分配什么时候出来？', '20号迎新系统开启后才会有学号；宿舍分配会在迎新系统中说明。', 'resolved', '2026-08-01'),
('qa-freshman-041', '学费现在能交吗？怎么交？', '学费统一通过南航统一身份认证登录 http://jiaofei.nuaa.edu.cn/ 提交，需要等学号出来后才能交。', 'resolved', '2026-08-01'),
('qa-freshman-042', '新生未满18岁无法开通银行卡，怎么交学费？', '可以让家长通过支付宝、微信代为支付。', 'resolved', '2026-08-01'),
('qa-freshman-043', '办理了国家助学贷款，缴费时怎么操作？', '不交学费部分，只交剩余的三项费用。', 'resolved', '2026-08-01'),
('qa-freshman-044', '申请生源地助学贷款需要办理绿色通道吗？', '需要。', 'resolved', '2026-08-01'),
('qa-freshman-045', '申请贫困补助要交什么材料？', '1. 注册账号：登录国家开发银行学生在线系统（https://sls.cdb.com.cn）或国家助学贷款APP注册； 2. 获取贷款申请表及认定申请表； 3. 准备身份证、户口簿原件； 4. 准备录取通知书（或学生证）原件或学信网学籍在线验证报告。', 'resolved', '2026-08-01'),
('qa-freshman-046', '开学要准备哪些证件？', '必带：身份证、高考准考证、录取通知书。根据个人情况携带：纸质档案、团员相关材料。另需近期免冠正面1寸彩照８张，建议留存电子版备用。', 'resolved', '2026-08-01'),
('qa-freshman-047', '上传的电子照片有什么要求？', '蓝底、白色上衣，头发不能遮住眉毛和脸颊，可以戴眼镜（具体以入学须知为准）。', 'resolved', '2026-08-01'),
('qa-freshman-048', '照片传不上去怎么办？', '换用电脑端上传，或换一个浏览器试试。', 'resolved', '2026-08-01'),
('qa-freshman-049', '户口要不要迁到学校？', '看个人意愿；如需迁移，开学后统一办理。', 'resolved', '2026-08-01'),
('qa-freshman-050', '迎新系统中的火车乘车区间起点站填什么？', '填“溧阳”。', 'resolved', '2026-08-01'),
('qa-freshman-051', '大学经历证明人怎么填？', '根据专业方向填写： ·伍玲玲：信息与计算科学、信息与计算科学+人工智能双学位、应用统计学 ·张大龙：材料科学与工程、应用化学、核工程类、新能源材料与器件、增材制造工程 ·何玉婷：计算机科学与技术、物联网工程、信息安全 ·朱函颍：人工智能、软件工程', 'resolved', '2026-08-01'),
('qa-freshman-052', '学习经历怎么填？', '按初中、高中、大学三段填写。', 'resolved', '2026-08-01'),
('qa-freshman-053', '生源地怎么填？', '在哪里参加高考就填哪里。', 'resolved', '2026-08-01'),
('qa-freshman-054', '南航天目湖校区的邮寄地址是什么？', '学校邮寄地址：江苏省溧阳市滨河东路29号（南京航空航天大学天目湖校区）。快递收货地：江苏省常州市溧阳市古县街道滨河东路南京航空航天大学天目湖校区B1菜鸟驿站。', 'resolved', '2026-08-01'),
('qa-freshman-055', '新生宿舍能提前入住吗？', '尽量按通知书上的报到时间；30号、31号两天都可以。', 'resolved', '2026-08-01'),
('qa-freshman-056', '天目湖校区寒暇假能留校吗？', '不能，寒暇假均封校，无法留校。', 'resolved', '2026-08-01'),
('qa-freshman-057', '有新生骨干训练营吗？', '有。会在正式报到前3天到校，参与培训并承担迎新筹备与志愿服务工作。可关注“南京航空航天大学学生服务”公众号留意招募通知。', 'resolved', '2026-08-01'),
('qa-freshman-058', '新生报到后要去体检吗？', '预约后按指定时间到校医院体检。', 'resolved', '2026-08-01'),
('qa-freshman-059', '档案什么时候可以邮寄？寄到哪？', '可以寄送至南航招生办。地址：江苏省南京市秦淮区御道街29号 南京航空航天大学；收件人：南航招生办；联系电话：025-84890508；邮编：210002。', 'resolved', '2026-08-01'),
('qa-freshman-060', '档案需要密封吗？', '团员档案和考生档案均需密封并盖骑缝章；团员证可不封在团员档案中，自行保管好、报到时携带。', 'resolved', '2026-08-01'),
('qa-freshman-061', '团组织关系怎么转接？', '智慧团建流程：团江苏省委 南航团委 牧星学院团委 搜自己的班级号（如0325001）→点击“选择”。纸质介绍信抬头统一写“南京航空航天大学牧星学院团委”。开学后再转就行，不着急。', 'resolved', '2026-08-01'),
('qa-freshman-062', '入团具体时间怎么看？', '登录智慧团建查看电子版入团志愿书，在上级团委审批建议处可见。', 'resolved', '2026-08-01'),
('qa-freshman-063', '有开学考试吗？考什么？', '有。考英语，决定未来分入三级班（大一上无法考四级）还是四级班。题型大多来自往年四六级真题，也有雅思和托福的部分题目。', 'resolved', '2026-08-01'),
('qa-freshman-064', '需要买英语听力用的调频耳机吗？', '不需要，考场内部有广播。', 'resolved', '2026-08-01'),
('qa-freshman-065', '选课有什么注意事项？', '（1）必修课都要选好，不要遗漏。 （2）选课分两轮：第一轮意愿值选课（价高者得），第二轮抢课。', 'resolved', '2026-08-01'),
('qa-freshman-066', '绩点怎么算？', '单科绩点 = （该门课分数 − 50）÷ 10；总绩点 = ∑(学分 × 绩点) ÷ 总学分，学分越高的课越重要。', 'resolved', '2026-08-01'),
('qa-freshman-067', '军训成绩怎么算？', '军训占2学分的必修绩点，成绩大多呈正态分布，室内军训给分相对偏低。', 'resolved', '2026-08-01'),
('qa-freshman-068', '“走进南京”/“走进南航”课程怎么学？', '有1学分，需达到观看时长，须原速播放。', 'resolved', '2026-08-01'),
('qa-freshman-069', '有早晚自习吗？', '有，大一需要参加早晚自习。', 'resolved', '2026-08-01'),
('qa-freshman-070', '开学后还有别的选拔吗？', '有一次长空创新班的选拔。', 'resolved', '2026-08-01'),
('qa-freshman-071', '大一可以带电脑吗？', '可以带；但工作日不允许用电脑进行娱乐活动。', 'resolved', '2026-08-01'),
('qa-freshman-072', '需要下载哪些APP？', 'i南航、学习通、龙猫校园、学信网、志愿汇、U校园。', 'resolved', '2026-08-01'),
('qa-freshman-073', '校园电信卡是什么？一定要办吗？', '相当于电话卡，办后网速会快一些，但不办也能使用校园网。', 'resolved', '2026-08-01'),
('qa-freshman-074', '校园卡/学工系统的照片怎么换？', '携带身份证前往师生服务大厅，使用现场自助拍照机更换。', 'resolved', '2026-08-01'),
('qa-freshman-075', '宿舍是自己选吗？', '不是自己选。按学号分配，连在一起的四个人住同一间。', 'resolved', '2026-08-01'),
('qa-freshman-076', '怎么查自己的宿舍？', 'i南航 → 顶部搜索“后勤服务” → 公寓服务 → 我的名片。', 'resolved', '2026-08-01'),
('qa-freshman-077', '宿舍床铺尺寸是多少？', '上床下桌。两张靠阳台的床是2米长，另外两张是1.9米，宽均为90cm；可与室友协商分配90×190和90×200两种规格。', 'resolved', '2026-08-01'),
('qa-freshman-078', '空调怎么选？', '选租赁。', 'resolved', '2026-08-01'),
('qa-freshman-079', '床上用品要提前带吗？', '可以到校后直接购买。', 'resolved', '2026-08-01'),
('qa-freshman-080', '宿舍能装床帘吗？', '上床下桌，可以装床帘。', 'resolved', '2026-08-01'),
('qa-freshman-081', '可以自己带吹风机吗？', '可以，1600W的也可以。', 'resolved', '2026-08-01'),
('qa-freshman-082', '宿舍柜子能上锁吗？', '预留了锁孔，可以自备锁。', 'resolved', '2026-08-01'),
('qa-freshman-083', '几点熄灯？会断电吗？', '晚上11点熄灯，但不断电。', 'resolved', '2026-08-01'),
('qa-freshman-084', '宿舍电梯什么时候开？', '平时不开放；放假、开学或有大件物品时会开放。', 'resolved', '2026-08-01'),
('qa-freshman-085', '普通话证书补办在哪里？', '师生服务大厅6号窗口。', 'resolved', '2026-08-01'),
('qa-freshman-086', '失物查询在哪个窗口？', '师生服务大厅8号窗口。', 'resolved', '2026-08-01'),
('qa-freshman-087', '出入境证件办理在哪？', '师生服务大厅3号公安政务窗口。', 'resolved', '2026-08-01'),
('qa-freshman-088', '校园卡照片换了吗？在哪换？', '师生服务大厅自助拍照机可以更换校园卡照片。', 'resolved', '2026-08-01'),
('qa-freshman-089', '退课、重修纸质材料交给谁？', '学院教务员。', 'resolved', '2026-08-01'),
('qa-freshman-090', '图书馆遗失物品去哪找？', '图书馆2楼咨询台（物品留存一周，无人认领移交学生事务服务中心）。', 'resolved', '2026-08-01'),
('qa-freshman-091', '天目湖校区有哪些建筑？', '教学楼：巡天楼、牧星楼、明慧楼；实验楼：笃行楼（物理实验室、机房、飞行实验室）、知行楼（常用做考场）；体育馆：健翔体育馆（含游泳馆、拳击馆、篮球馆）、风雨操场（西操）、东操场（附近有网球场）；其他：综合服务楼、师生服务大厅、校医院、食堂（东篱靠近B5、南山靠近B3）。', 'resolved', '2026-08-01'),
('qa-freshman-092', '天目湖校区能骑自行车吗？', '校内不能骑自行车。校外出行可以选择打车或骑共享电动车。', 'resolved', '2026-08-01'),
('qa-freshman-093', '天目湖校区离溧阳站多远？', '很近，打车5分钟左右。', 'resolved', '2026-08-01'),
('qa-freshman-094', '天目湖校区社团怎么加入？', '开学时许多社团会在表白墙上发布招募信息，可以直接申请加入QQ群；军训结束后会有统一的社团招新活动。', 'resolved', '2026-08-01'),
('qa-freshman-095', '师生服务大厅能办什么业务？', '主要办理学生证、缴纳学费、办理交通银行卡等。窗口分工：3号窗口出入境证件；6号窗口普通话证书补办；8号窗口失物查询；另有自助拍照机换校园卡照片。', 'resolved', '2026-08-01'),
('qa-freshman-096', '天目湖校区食堂有哪些？', '两个食堂：东篱（靠近B5宿舍）和南山（靠近B3宿舍）。', 'resolved', '2026-08-01'),
('qa-freshman-097', '校医院能借拐杖吗？', '可以，需100元现金押金，每日使用费1元。', 'resolved', '2026-08-01'),
('qa-freshman-098', '致元书院是什么？', '致元书院是南航设立的书院之一，服务于天目湖校区新生，涵盖材料科学与技术学院、数学学院、计算机科学与技术学院/软件学院、人工智能学院这4个专业学院共18个专业。', 'resolved', '2026-08-01'),
('qa-freshman-099', '“致元”这个名字是什么意思？', '“致”取自牧星学院“问·致”文化，意为达到；“元”取自《周易·乾卦》“元者，善之长也”及《说文解字》“元，始也”，意为万物本源。合起来是“探寻本元”，象征格物致知的科学精神。', 'resolved', '2026-08-01'),
('qa-freshman-100', '致元书院的文化理念是什么？', '“抱朴守真，致本归元”，出自《道德经》。前四字讲坚守质朴本真、不堕浮华，后四字讲探询事物本质、回归初心本源。', 'resolved', '2026-08-01'),
('qa-freshman-101', '致元书院的IP形象阿源是怎么来的？', '形象取自猿猴——“猿”音同“元”，“猿”又是人类起源。取名“阿源”意在“为有源头活水来”，寓意既要掌握知识的源头活水，也要寻得生活的源头活水。', 'resolved', '2026-08-01'),
('qa-freshman-102', '什么是致元书院的“5C”育人体系？', '5个C分别是：Center（以学生为中心）、Culture（文化思政融合）、Circle（品牌矩阵赋能）、Creativity（创新实践培育核心竞争力）、Career（生涯就业护航）。', 'resolved', '2026-08-01'),
('qa-freshman-103', '致元书院有哪些品牌活动？', '分两个系列：“元梦”系列（思想引领）：元梦圆桌派、元梦大讲堂、元梦山湖号、“BOOK思议”读书会。“元气”系列（行动塑造）：元气夜校、元气大扫除、元气周末跚、元气田野、节日特辑。', 'resolved', '2026-08-01'),
('qa-freshman-104', '元气夜校可以学什么？', '内容非常丰富：既有非遗传承人亲授的竹雕、籮刻，也有PPT制作、合唱训练等实用技能，还有拳击、乒乓球等体育项目，是书院人气最高的“第二课堂”。', 'resolved', '2026-08-01'),
('qa-freshman-105', '致元书院涵盖哪些专业？', '一共18个专业：材料学院：材料科学与工程（含拔尖创新班）、新能源材料与器件、增材制造工程、应用化学、核工程类；数学学院：信息与计算科学、应用统计学、信息与计算科学+人工智能双学位、应用统计学+计算机科学与技术双学位；计算机学院/软件学院：计算机科学与技术（含拔尖创新班）、软件工程、信息安全、物联网工程；人工智能学院：人工智能（含拔尖创新班）、具身智能。', 'resolved', '2026-08-01'),
('qa-freshman-106', '“元点”辅导员工作室是做什么的？', '是书院开展职业生涯规划教育的载体，构建了“五位一体”生涯教育体系：生涯沙盘、生涯剧本杀、生涯嘉年华、生涯咨询、院本化贯通式生涯课程，激发学生生涯内驱力。', 'resolved', '2026-08-01');
